    for filename, fixity_info in fixity["fixity"].items():
        if filename not in manifest_files_set:
            raise ValueError(f"File '{filename}' is referenced in the fixity block but not in the manifest")
        if not isinstance(fixity_info, dict):
            raise ValueError(f"Fixity information for file '{filename}' is not a dictionary")
        for fixity_key, fixity_value in fixity_info.items():
