            yield value

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None

    frequency_regex = r"^(?P<value>\d+)\s+(?P<unit>\w+)$"
    match = re.match(frequency_regex, frequency)
    if match is None:
        raise ValueError("Invalid frequency: {}".format(frequency))

    value = int(match.group("value"))
    unit = match.group("unit").lower()
    if unit not in ["year", "month", "week", "day", "hour", "minute", "second"]:
        raise ValueError("Invalid frequency: {}".format(frequency))

    return datetime.timedelta(**{unit: value})

