def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re

    _PROTOCOL_RE = re.compile(r'(https?:\/\/.*?)(?=\,|\s|$|[)])', re.I)
    _WIKI_RE = re.compile(r'\[\[([\w\s]+)\]\]', re.I)
    _URL_RE = re.compile(r'https?:\/\/[\w\/:%#\$&\?\(\)~\.=\+\-]+', re.I)

    def _add_link_attributes(m):
        url = m.group(0)
        if not _URL_RE.match(url):
            return url
        else:
            return '<a href="{}">{}</a>'.format(url, url)

    def _linkify_textual_links(m):
        text = m.group(0)
        url = None
        if text.startswith('http'):
            url = text
        elif text.startswith('www.'):
            url = 'http://{}'.format(text)
        else:
            url = _WIKI_RE.sub(r'https://en.wikipedia.org/wiki/\1', text)
        return '<a href="{}">{}</a>'.format(url, text)

    text = _PROTOCOL_RE.sub(_add_link_attributes, text)
    text = _URL_RE.sub(_linkify_textual_links, text)
    return text

