def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    try:
        with open(os.path.join(plugin_dir, 'plugin.spec')) as f:
            spec_dict = json.load(f)
    except FileNotFoundError:
        raise InvalidPluginSpecError("Plugin spec file not found in '{}'".format(plugin_dir))
    except json.decoder.JSONDecodeError:
        raise InvalidPluginSpecError("Invalid plugin spec file in '{}'".format(plugin_dir))

    flatten_dict = {}
    for key, value in spec_dict.items():
        if isinstance(value, dict):
            for subkey, subvalue in value.items():
